INSERT INTO public.materias_benner (nome, descricao) VALUES
('Abono Assiduidade', 'Reclamante alega que não foi concedida a folga assiduidade prevista na CCT dos bancários. O pedido é feito por empregados do banco ou por terceiros que pedem enquadramento bancário ou vínculo de emprego com o Banco por ilicitude da terceirização'),
